  select(major) |&gt;
  mutate(view_stat = str_view(major, pattern = "[sS]tat", match = NA),
         is_stats  = str_detect(major, pattern = "[sS]tat")) |&gt;
  summarize(p_stat = mean(is_stats))



# A tibble: 1 × 1
  p_stat
   &lt;dbl&gt;
